const key=async(value,modifiers=0)=>{const code=/^[0-9]$/.test(value)?'Digit'+value:value==='Escape'?'Escape':value==='Enter'?'Enter':'Key'+value.toUpperCase(),vk=value==='Escape'?27:value==='Enter'?13:value.toUpperCase().charCodeAt(0);for(const type of ['rawKeyDown','keyUp'])await send('Input.dispatchKeyEvent',{type,key:value,code,windowsVirtualKeyCode:vk,modifiers});};
