const findControl=(s,key)=>{for(const prefix of ['morph','scene','layer','transform'])if(s[prefix+'_controls']?.[key])return {rect:s[prefix+'_controls'][key],enabled:s[prefix+'_controls_enabled']?.[key],prefix};return null;};
