    for(let face=0;face<mesh.triangles.length;face++){const [a,b,c]=mesh.triangles[face].map(i=>mesh.positions[i].map(Math.fround)),e1=subtract(b,a),e2=subtract(c,a),p=cross(direction,e2),det=dot(e1,p);if(Math.abs(det)<1e-12)continue;const tvec=subtract(origin,a),u=dot(tvec,p)/det;if(u<0||u>1)continue;const q=cross(tvec,e1),v=dot(direction,q)/det;if(v<0||u+v>1)continue;const t=dot(e2,q)/det;if(t>1e-9&&(!best||t<best.t))best={face,t,barycentric:[1-u-v,u,v],point:origin.map((x,i)=>x+t*direction[i])};}
    if(best)return {...best,screen,camera,oracle:'Independent f64 inverse view-projection + closest positive ray/triangle intersection; rendered data read-only'};
